import { Noto_Sans_KR, Recursive } from "next/font/google";

/**
 * The two voices of VARIFLEX 바리플렉스 — type that stretches.
 *
 * Recursive — the variable voice. A single variable font with weight (300..900)
 *   and slant (0..-15) axes; the wordmark physically morphs from thin-extended
 *   to bold-condensed as the CSS custom properties --vf-w (font-weight) and
 *   --vf-s (slnt) are driven by the pointer. The hero IS the axis morph.
 *
 * Noto Sans KR — every Hangul glyph. A clean modern grotesque so the Korean
 *   sub-line reads clearly on the warm light ground.
 *
 * styles.css consumes these as var(--font-recursive) / var(--font-noto-sans-kr);
 * page.tsx applies the .variable classes on the entry root.
 */
export const recursive = Recursive({
  // Recursive is a variable font; request the full variable instance so the
  // weight + slnt axes can be driven live from CSS (font-weight / font-style).
  // next/font exposes non-weight variable axes via `axes`.
  weight: "variable",
  axes: ["slnt", "CASL", "MONO", "CRSV"],
  subsets: ["latin"],
  variable: "--font-recursive",
  display: "swap",
});

export const notoSansKR = Noto_Sans_KR({
  weight: ["400", "500", "700"],
  subsets: ["latin"],
  variable: "--font-noto-sans-kr",
  display: "swap",
});

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class (the name styles.css expects). Pre-reveal
 * states (opacity/translate) live in styles.css and are gated behind the
 * `.neon-js` root class, so all content is fully visible when JavaScript
 * never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms apart
 * — the street's cadence.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (reduced || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { recursive, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

const TITLE = "VARIFLEX";

/**
 * VARIFLEX 바리플렉스 — type that stretches. The signature is the variable
 * axis morph: a huge wordmark in Recursive whose font-weight (300..900) and
 * slnt (0..-15) are driven by the pointer's X (and a touch of Y), so the
 * glyphs physically swing from thin-extended to bold-slanted in real time.
 * The axis readout (wght / slnt) updates live beside it. Under reduced motion
 * the wordmark holds a composed mid-axis pose.
 *
 * `.variflex-js` is added on mount so the no-JS markup is the finished page:
 * the wordmark at its default axis, copy readable.
 */
export default function VariflexPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const stageRef = useRef<HTMLDivElement | null>(null);
  const readoutRef = useRef<HTMLSpanElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("variflex-js");
    const id = requestAnimationFrame(() => root.classList.add("is-mounted"));
    window.parent?.postMessage({ type: "oneshot:ready", slug: "variflex" }, "*");
    return () => cancelAnimationFrame(id);
  }, []);

  // Drive the variable axes from the pointer. X → weight, Y → slant.
  // Damped in a rAF loop so the morph feels like a spring, not a snap.
  useEffect(() => {
    const stage = stageRef.current;
    if (!stage || reduced) return;
    let raf = 0;
    let tw = 600; // target weight
    let ts = 0; // target slnt
    let cw = tw;
    let cs = ts;
    const onMove = (e: PointerEvent) => {
      const r = stage.getBoundingClientRect();
      const w = Math.max(1, r.width);
      const h = Math.max(1, r.height);
      const nx = (e.clientX - r.left) / w; // 0..1
      const ny = (e.clientY - r.top) / h; // 0..1
      // weight 300 (left) .. 900 (right); slnt 0 (top) .. -15 (bottom)
      tw = 300 + nx * 600;
      ts = 0 - ny * 15;
      if (!raf) raf = requestAnimationFrame(tick);
    };
    const tick = () => {
      cw += (tw - cw) * 0.18;
      cs += (ts - cs) * 0.18;
      if (!Number.isFinite(cw)) cw = 600;
      if (!Number.isFinite(cs)) cs = 0;
      stage.style.setProperty("--vf-w", cw.toFixed(0));
      stage.style.setProperty("--vf-s", cs.toFixed(1));
      if (readoutRef.current) {
        readoutRef.current.textContent = `wght ${cw.toFixed(0)} · slnt ${cs.toFixed(1)}`;
      }
      if (Math.abs(tw - cw) > 0.6 || Math.abs(ts - cs) > 0.06) {
        raf = requestAnimationFrame(tick);
      } else {
        raf = 0;
      }
    };
    window.addEventListener("pointermove", onMove, { passive: true });
    return () => {
      window.removeEventListener("pointermove", onMove);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [reduced]);

  return (
    <div
      ref={rootRef}
      className={`${recursive.variable} ${notoSansKR.variable} variflex-root`}
    >
      <div className="variflex-paper" aria-hidden="true" />
      <div ref={revealRef} className="variflex-doc">
        <header className="vf-hero">
          <p className="vf-kicker" data-reveal="">
            <span lang="ko">가변폰트 쇼케이스</span> · VARIABLE TYPE · wght 300–900 · slnt 0–-15
          </p>
          <div ref={stageRef} className="vf-stage" data-reveal="">
            <h1 className="vf-title" aria-label={TITLE}>
              <span aria-hidden="true" className="vf-title__row">
                {TITLE.split("").map((ch, i) => (
                  <span
                    key={i}
                    className="variflex-glyph"
                    style={{ "--vf-i": i } as CSSProperties}
                  >
                    {ch}
                  </span>
                ))}
              </span>
            </h1>
            <p className="vf-axis-readout" aria-live="off">
              <span ref={readoutRef}>wght 600 · slnt 0.0</span>
              <span className="vf-axis-hint" lang="ko">
                {" "}— 움직여 자형을 늘려라
              </span>
            </p>
          </div>
          <p className="vf-sub" data-reveal="">
            <span lang="ko">늘어나는 자형.</span> Type that stretches — move the
            pointer and the axes bend: thin and extended left, bold and slanted
            right.
          </p>
        </header>

        <section className="vf-axes" aria-labelledby="vf-axes-title">
          <div className="vf-sechead" data-reveal="">
            <p className="vf-eyebrow">
              02 — <span lang="ko">두 축</span> · the axes
            </p>
            <h2 id="vf-axes-title" className="vf-secthead__title">
              two axes, one glyph
            </h2>
            <p className="vf-secthead__kr" lang="ko">
              무게와 기울기 — 같은 글자가 다른 형태로.
            </p>
          </div>
          <div className="vf-axegrid">
            <article className="vf-axecard" data-reveal="">
              <p className="vf-axecard__no">01</p>
              <p className="vf-axecard__demo vf-axecard__demo--thin" aria-hidden="true">Aa</p>
              <p className="vf-axecard__h">
                wght · <span lang="ko">무게</span>
              </p>
              <p className="vf-axecard__b">
                <span lang="ko">왼쪽은 얇고, 오른쪽은 두껍다.</span> Left is
                thin (300), right is heavy (900) — the stroke fills out.
              </p>
            </article>
            <article className="vf-axecard" data-reveal="">
              <p className="vf-axecard__no">02</p>
              <p className="vf-axecard__demo vf-axecard__demo--slant" aria-hidden="true">Aa</p>
              <p className="vf-axecard__h">
                slnt · <span lang="ko">기울기</span>
              </p>
              <p className="vf-axecard__b">
                <span lang="ko">위는 곧고, 아래는 기운다.</span> Top is upright
                (0°), bottom leans (-15°) — the italics live in the same font.
              </p>
            </article>
          </div>
        </section>

        <section className="vf-ramp" aria-labelledby="vf-ramp-title">
          <div className="vf-sechead" data-reveal="">
            <p className="vf-eyebrow">
              03 — <span lang="ko">스펙트럼</span> · the spectrum
            </p>
            <h2 id="vf-ramp-title" className="vf-secthead__title">
              the full sweep
            </h2>
            <p className="vf-secthead__kr" lang="ko">
              한 글자가 여섯 단계로.
            </p>
          </div>
          <div className="vf-ramp-row" data-reveal="" aria-hidden="true">
            <span className="vf-ramp-ch" style={{ fontWeight: 300, fontStyle: "normal" }}>바</span>
            <span className="vf-ramp-ch" style={{ fontWeight: 500, fontStyle: "normal" }}>A</span>
            <span className="vf-ramp-ch" style={{ fontWeight: 700, fontStyle: "normal" }}>A</span>
            <span className="vf-ramp-ch" style={{ fontWeight: 900, fontStyle: "normal" }}>A</span>
            <span className="vf-ramp-ch" style={{ fontWeight: 700, fontVariationSettings: "'slnt' -8" }}>A</span>
            <span className="vf-ramp-ch" style={{ fontWeight: 900, fontVariationSettings: "'slnt' -15" }}>A</span>
          </div>
          <p className="vf-ramp-cap" data-reveal="">
            <span lang="ko">얇고 곧은 것에서 굵고 기운 것까지.</span> From thin &amp;
            upright to bold &amp; slanted — one variable font, every step.
          </p>
        </section>

        <footer className="vf-foot" data-reveal="">
          <p className="vf-foot__brand">
            VARIFLEX <span lang="ko">바리플렉스</span> ·{" "}
            <span lang="ko">늘어나는 자형</span>
          </p>
          <p className="vf-foot__line">
            <span lang="ko">순수 코드 — 이미지 없음.</span> Pure code ·
            Recursive variable font · MIT
          </p>
        </footer>
      </div>
    </div>
  );
}

/* ==========================================================================
   VARIFLEX 바리플렉스 — type that stretches · no.065
   kinetic-variable · warm-light / accent-red · variable font axis morph
   Scoped by convention to .variflex-root; classes prefixed vf- / variflex-.
   ========================================================================== */

.variflex-root {
  --vf-bg: #fbf3ee;
  --vf-warm: #f4e6da;
  --vf-deep: #efe0d2;
  --vf-text: #2a1a14;
  --vf-mute: #7a6457;
  --vf-quiet: #b6a392;
  --vf-red: #ff4d6d;
  --vf-red-soft: rgba(255, 77, 109, 0.5);
  --vf-font-display: var(--font-recursive), "Recursive", system-ui, sans-serif;
  --vf-font-kr: var(--font-noto-sans-kr), "Noto Sans KR", sans-serif;
  --vf-ease: cubic-bezier(0.16, 1, 0.3, 1);

  position: relative;
  min-height: 100vh;
  margin: 0;
  background:
    radial-gradient(120% 90% at 50% 0%, rgba(255, 77, 109, 0.07), transparent 60%),
    radial-gradient(80% 60% at 50% 100%, rgba(255, 77, 109, 0.05), transparent 70%),
    linear-gradient(180deg, var(--vf-warm) 0%, var(--vf-bg) 50%, var(--vf-warm) 100%);
  color: var(--vf-text);
  font-family: var(--vf-font-kr);
  font-weight: 400;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
  overflow-x: clip;
}

.variflex-root :lang(ko) {
  font-family: var(--vf-font-kr);
}

.variflex-root ::selection {
  background: var(--vf-red);
  color: #fff;
}

.variflex-root :focus-visible {
  outline: 2px solid var(--vf-red);
  outline-offset: 3px;
}

/* ---- Atmospheric depth: warm paper grain behind all ---- */
.variflex-paper {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image:
    radial-gradient(rgba(122, 100, 87, 0.05) 1px, transparent 1px),
    radial-gradient(rgba(122, 100, 87, 0.04) 1px, transparent 1px);
  background-size: 22px 22px, 17px 17px;
  background-position: 0 0, 11px 8px;
  mask-image: radial-gradient(110% 90% at 50% 40%, #000 30%, transparent 90%);
  -webkit-mask-image: radial-gradient(110% 90% at 50% 40%, #000 30%, transparent 90%);
}

.variflex-doc {
  position: relative;
  z-index: 2;
  max-width: 1160px;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3.5rem);
}

/* ---- Reveal gating (JS-dependent pre-states) ---- */
.variflex-js [data-reveal] {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 800ms var(--vf-ease), transform 800ms var(--vf-ease);
}
.variflex-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

/* ---- Hero / the morph stage ---- */
.vf-hero {
  padding: clamp(48px, 10vh, 96px) 0 clamp(28px, 5vh, 48px);
  text-align: center;
}
.vf-kicker {
  margin: 0 0 clamp(18px, 4vh, 32px);
  font-family: var(--vf-font-display);
  font-size: clamp(0.7rem, 1vw, 0.82rem);
  font-weight: 500;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--vf-red);
}
.vf-stage {
  /* the axis morph: --vf-w drives font-weight, --vf-s drives slnt.
     Defaults are a composed mid-axis pose so no-JS looks intentional. */
  --vf-w: 600;
  --vf-s: 0;
  position: relative;
  cursor: ew-resize;
}
.vf-title {
  margin: 0;
  font-family: var(--vf-font-display);
  font-weight: var(--vf-w, 600);
  font-size: clamp(3.4rem, 18vw, 16rem);
  line-height: 0.86;
  letter-spacing: -0.02em;
  /* The wordmark IS the concept: accent-red fill with a soft warm shadow
     and a faint red ghost offset — the type feels pressed into warm paper. */
  color: var(--vf-red);
  font-variation-settings: "'MONO' 0, 'CASL' 0, 'CRSV' 0, 'slnt' var(--vf-s, 0)";
  text-shadow:
    0 4px 0 rgba(255, 77, 109, 0.12),
    0 10px 30px rgba(255, 77, 109, 0.18);
  transition: font-weight 80ms linear, font-variation-settings 80ms linear;
}
.vf-title__row {
  display: block;
}
.vf-axis-readout {
  margin: 14px 0 0;
  font-family: var(--vf-font-display);
  font-size: clamp(0.78rem, 1.2vw, 0.95rem);
  font-weight: 500;
  letter-spacing: 0.12em;
  color: var(--vf-mute);
}
.vf-axis-readout span:first-child {
  color: var(--vf-red);
  font-variant-numeric: tabular-nums;
}
.vf-axis-hint {
  color: var(--vf-quiet);
}
.vf-sub {
  margin: 22px auto 0;
  max-width: 44ch;
  font-size: clamp(0.98rem, 1.2vw, 1.1rem);
  color: var(--vf-mute);
}
.vf-sub :lang(ko) {
  color: var(--vf-text);
  font-weight: 500;
}

/* ---- Glyph reveal (per-letter) ---- */
.variflex-glyph {
  display: inline-block;
}
.variflex-js .variflex-glyph {
  opacity: 0;
  transform: translateY(0.35em);
  transition: opacity 700ms var(--vf-ease), transform 700ms var(--vf-ease);
  transition-delay: calc(var(--vf-i) * 70ms + 150ms);
}
.variflex-js.is-mounted .variflex-glyph {
  opacity: 1;
  transform: none;
}

/* ---- Axes section ---- */
.vf-axes {
  padding: clamp(24px, 5vh, 48px) 0;
}
.vf-sechead {
  text-align: center;
  margin-bottom: clamp(24px, 4vh, 40px);
}
.vf-eyebrow {
  margin: 0 0 10px;
  font-family: var(--vf-font-display);
  font-size: 0.7rem;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--vf-red);
}
.vf-secthead__title {
  margin: 0 0 8px;
  font-family: var(--vf-font-display);
  font-weight: 700;
  font-size: clamp(1.7rem, 4vw, 2.6rem);
  text-transform: lowercase;
  letter-spacing: -0.01em;
  color: var(--vf-text);
}
.vf-secthead__kr {
  margin: 0;
  color: var(--vf-mute);
  font-size: 0.98rem;
}
.vf-axegrid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 18px;
}
.vf-axecard {
  position: relative;
  padding: 24px;
  border: 1px solid rgba(255, 77, 109, 0.2);
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.5), rgba(244, 230, 218, 0.5));
  text-align: left;
}
.vf-axecard__no {
  margin: 0 0 10px;
  font-family: var(--vf-font-display);
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  color: var(--vf-red);
}
.vf-axecard__demo {
  margin: 0 0 14px;
  font-family: var(--vf-font-display);
  font-size: clamp(3rem, 8vw, 4.5rem);
  line-height: 1;
  color: var(--vf-red);
}
.vf-axecard__demo--thin {
  font-weight: 300;
  background: linear-gradient(90deg, var(--vf-red), #c93551 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
.vf-axecard__demo--slant {
  font-weight: 700;
  font-variation-settings: "'slnt' -12";
}
.vf-axecard__h {
  margin: 0 0 8px;
  font-family: var(--vf-font-display);
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--vf-text);
}
.vf-axecard__b {
  margin: 0;
  font-size: 0.92rem;
  color: var(--vf-mute);
  line-height: 1.7;
}
.vf-axecard__b :lang(ko) {
  color: var(--vf-text);
}

/* ---- Ramp / spectrum ---- */
.vf-ramp {
  padding: clamp(24px, 5vh, 48px) 0;
}
.vf-ramp-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: clamp(6px, 2vw, 22px);
  max-width: 720px;
  margin: 0 auto 18px;
}
.vf-ramp-ch {
  font-family: var(--vf-font-display);
  font-size: clamp(2.4rem, 9vw, 5rem);
  line-height: 1;
  color: var(--vf-red);
  text-shadow: 0 6px 18px rgba(255, 77, 109, 0.18);
}
.vf-ramp-cap {
  margin: 0 auto;
  max-width: 44ch;
  text-align: center;
  font-size: 0.95rem;
  color: var(--vf-mute);
}
.vf-ramp-cap :lang(ko) {
  color: var(--vf-text);
}

/* ---- Footer ---- */
.vf-foot {
  margin-top: clamp(40px, 8vh, 80px);
  padding: clamp(28px, 5vh, 48px) 0;
  border-top: 1px solid rgba(255, 77, 109, 0.2);
  text-align: center;
}
.vf-foot__brand {
  margin: 0 0 6px;
  font-family: var(--vf-font-display);
  font-weight: 700;
  font-size: 0.86rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--vf-text);
}
.vf-foot__line {
  margin: 0;
  font-size: 0.8rem;
  color: var(--vf-quiet);
}

/* ---- Reduced motion: axis holds the composed mid pose ---- */
@media (prefers-reduced-motion: reduce) {
  .variflex-js [data-reveal],
  .variflex-js .variflex-glyph {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }
  .vf-title { transition: none !important; }
}

@media (max-width: 560px) {
  .vf-stage { cursor: default; }
}
